-- Generated by model/lib/sql/generate.mjs. Loads Price Increase IN from cells/Price Increase IN.csv in the folder of input cells. Two rows for one cell add up.
INSERT OR REPLACE INTO "Price Increase IN" SELECT coalesce(k0."Brand", error('cells name a member Brand does not have: ' || c."Brand")), coalesce(k1."Versions", error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k2."Years", error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE)
FROM read_csv('cells/Price Increase IN.csv', header = true, all_varchar = true) c LEFT JOIN "dim Brand" k0 ON k0.name = c."Brand" LEFT JOIN "dim Versions" k1 ON k1.name = c."Versions" LEFT JOIN "dim Years" k2 ON k2.name = c."Years"
GROUP BY ALL;
